class PackedInfeasibleContinuationTest {

	private static final PackedCostModel COSTS = new PackedCostModel() {
		@Override
		public double estimateRows(PackedQueryView query, int relationId) {
			return query.isBindingSetAssignment(relationId) ? query.bindingAssignmentRowCount(relationId)
					: query.isStatementPattern(relationId) ? 18.0d : Double.NaN;
		}

		@Override
		public void estimate(PackedQueryView query, int relationId, PackedCostContext context,
				PackedCostEstimate output) {
			double local = estimateRows(query, relationId);
			if (context.prefixRelationCount() == 0) {
				output.setRows(local, local);
			} else {
				output.setContextualRows(context.prefixRows() * local, local);
			}
		}
	};

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void rejectedDependentValuesContinuationRetainsLegalIndependentPlans(boolean filtered) {
		TupleExpr source = PackedPlanDifferentialSupport.parse("""
				SELECT ?enc ?cond ?practitioner WHERE {
				  VALUES ?code { "one" "two" }
				  VALUES ?severity { "primary" "secondary" }
				  ?enc :condition ?cond ; :handledBy ?practitioner .
				  ?cond :code ?code ; :severity ?severity .
				  %s
				}
				""".formatted(filtered ? "FILTER(?severity != \"none\")" : ""));
		Model data = PackedPlanDifferentialSupport.model();
		for (int row = 0; row < 2; row++) {
			PackedPlanDifferentialSupport.add(data, "enc" + row, "condition",
					PackedPlanDifferentialSupport.iri("cond" + row));
			PackedPlanDifferentialSupport.add(data, "enc" + row, "handledBy",
					PackedPlanDifferentialSupport.iri("practitioner" + row));
			PackedPlanDifferentialSupport.add(data, "cond" + row, "code",
					PackedPlanDifferentialSupport.VF.createLiteral(row == 0 ? "one" : "two"));
			PackedPlanDifferentialSupport.add(data, "cond" + row, "severity",
					PackedPlanDifferentialSupport.VF.createLiteral(row == 0 ? "primary" : "secondary"));
		}
		List<String> expected = PackedPlanDifferentialSupport.evaluate(data, source);
		assertEquals(2, expected.size());
		PackedPlanningResult result = PackedCascadesPlanner.optimize(source.clone(), OptimizationGoal.root(), COSTS);
		assertTrue(Double.isFinite(result.totalCost()));
		assertTrue(Double.isFinite(result.outputRows()));
		assertEquals(expected, PackedPlanDifferentialSupport.evaluate(data, result.selectedPlan()),
				"discarding an infeasible alternative must preserve the legal plan and result bag");
	}

	@ParameterizedTest
	@CsvSource({ "false,false", "false,true", "true,false", "true,true" })
	void protectedSubqueryAlternativesKeepLegalIndependentCompletions(boolean before, boolean nested) {
		String finite = "{ SELECT ?o WHERE { VALUES ?o { 1 2 } } }";
		if (nested) {
			finite = "{ SELECT ?o WHERE { " + finite + " } }";
		}
		TupleExpr source = PackedPlanDifferentialSupport.parse("""
				SELECT ?s ?o ?v WHERE {
				  %s
				  ?s :p ?o ; :q ?v . ?v :r ?o .
				  %s
				}
				""".formatted(before ? finite : "", before ? "" : finite));
		Model data = PackedPlanDifferentialSupport.model();
		for (int row = 1; row <= 2; row++) {
			PackedPlanDifferentialSupport.add(data, "s" + row, "p",
					PackedPlanDifferentialSupport.VF.createLiteral(BigInteger.valueOf(row)));
			PackedPlanDifferentialSupport.add(data, "s" + row, "q", PackedPlanDifferentialSupport.iri("v" + row));
			PackedPlanDifferentialSupport.add(data, "v" + row, "r",
					PackedPlanDifferentialSupport.VF.createLiteral(BigInteger.valueOf(row)));
		}
		List<String> expected = PackedPlanDifferentialSupport.evaluate(data, source);
		assertEquals(2, expected.size());
		PackedPlanningResult result = PackedCascadesPlanner.optimize(source.clone(), OptimizationGoal.root(), COSTS);
		assertTrue(Double.isFinite(result.totalCost()));
		assertTrue(Double.isFinite(result.outputRows()));
		assertEquals(expected, PackedPlanDifferentialSupport.evaluate(data, result.selectedPlan()));
	}

	@Test
	void everySmallWorkBudgetStopsWithoutClaimingAnUnexplainedTraversalFailure() {
		TupleExpr source = PackedPlanDifferentialSupport.parse("""
				SELECT ?enc ?cond ?practitioner WHERE {
				  VALUES ?code { "one" "two" }
				  VALUES ?severity { "primary" "secondary" }
				  ?enc :condition ?cond ; :handledBy ?practitioner .
				  ?cond :code ?code ; :severity ?severity .
				}
				""");
		for (int limit = 1; limit <= 512; limit++) {
			int workLimit = limit;
			assertDoesNotThrow(() -> PackedCascadesPlanner.optimize(source.clone(),
					OptimizationGoal.root().asBudgeted(Duration.ZERO, workLimit), COSTS),
					"an actual early stop must retain a budget cause at work limit " + workLimit);
		}
	}

	@Test
	void nullableRequiredFrameDeclinesBothPhysicalOrientationsWithoutWeakeningTheFence() {
		TupleExpr source = PackedPlanDifferentialSupport.parse("""
				SELECT * WHERE {
				  VALUES ?endpoint { <urn:remote> }
				  { ?node :endpoint ?endpoint } UNION { VALUES ?other { 1 } }
				  SERVICE ?endpoint { ?subject :p ?object }
				}
				""");
		PackedQuery query = PackedQueryCodec.encodeForPlanning(source);
		int nullableProvider = 0;
		int requiredConsumer = 0;
		for (int relation = 1; relation <= query.relationCount(); relation++) {
			if (query.relOperator(relation) == PackedRelOp.UNION) {
				nullableProvider = relation;
			} else if (query.relOperator(relation) == PackedRelOp.SERVICE) {
				requiredConsumer = relation;
			}
		}
		assertTrue(nullableProvider > 0 && requiredConsumer > 0);
		assertTrue(query.maskCardinality(query.relRequiredInputMaskId(requiredConsumer)) > 0,
				"the actual SERVICE invocation depends on its preceding assured endpoint producer");
		assertTrue(query.masksIntersect(query.relOutputMaskId(nullableProvider),
				query.relRequiredInputMaskId(requiredConsumer)));
		assertFalse(query.maskContainsAll(query.relAssuredMaskId(nullableProvider),
				query.relRequiredInputMaskId(requiredConsumer)));
		int[] prefix = { nullableProvider };
		assertFalse(PackedInputFrameScheduling.dependent(query, prefix, 1, requiredConsumer));
		assertFalse(PackedInputFrameScheduling.independent(query, prefix, 1, requiredConsumer));
		assertFalse(PackedInputFrameScheduling.dependent(query, prefix, 1, new int[] { requiredConsumer }, 0, 1));
		assertFalse(PackedInputFrameScheduling.independent(query, prefix, 1, new int[] { requiredConsumer }, 0, 1));
	}

	@Test
	void finiteCandidateArenaStillRejectsAnUnavailableInfiniteScore() {
		PackedCandidateArena arena = new PackedCandidateArena(new PackedSearchBudget(Long.MAX_VALUE, Long.MAX_VALUE));
		assertThrows(IllegalArgumentException.class,
				() -> arena.append(1, 1, 1, 1, 0, 0, 1, Double.POSITIVE_INFINITY));
		assertEquals(0, arena.size());
	}
}
